import {summarize,viewRecord,predict,roomGroups,dailySummaries,businessName} from './model.mjs?v=18';
import {cloud,remoteSource,requestData,requestStatus,requestRefresh} from './data-client.mjs?v=18';
import {createPriceModule} from './prices.mjs?v=18';
const $=id=>document.getElementById(id);
function applyTheme(theme){const light=theme==='light';document.documentElement.dataset.theme=light?'light':'dark';$('theme-toggle').setAttribute('aria-checked',String(light));document.querySelector('meta[name="theme-color"]').content=light?'#f5f5f7':'#101011';try{localStorage.setItem('product-workbench-theme',light?'light':'dark');}catch{}}
try{applyTheme(localStorage.getItem('product-workbench-theme')||'light');}catch{applyTheme('light');}

const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Z"/><path d="m3 8 9 5 9-5M12 13v9M7.5 5.5l9 5v4"/>',calculator:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M8 11h1m5 0h2M8 15h1m5 0h2M8 19h1m5 0h2"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 4 16 4 16 0V5M4 12v7c0 4 16 4 16 0v-7"/>',external:'<path d="M14 3h7v7M21 3 11 13"/><path d="M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-2l2 3M4 16l2 3a7 7 0 0 0 12-2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',orders:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 9h6m-6 4h6m-6 4h4"/>',money:'<path d="m7 3 5 6 5-6M5 10h14M5 15h14m-7-6v12"/>',trend:'<path d="M3 19V5m0 14h18M7 14l4-4 4 2 6-7m-5 0h5v5"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.box}</svg>`;
document.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const pct=v=>v==null?'—':`${fmt(v*100,2)}%`;
const money=v=>v==null?'—':`¥${fmt(v,0)}`;
const compact=v=>v>=10000?`${fmt(v/10000,2)}<span class="unit">万</span>`:fmt(v);
const time=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false,month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'尚未成功刷新';
const state={data:null,page:'overview',filters:{group:'',room:'',anchor:'',from:'',to:''},search:'',sort:'orders',tablePage:1,rateMode:'orders',status:null,boardTabs:{},boardSort:'orders',reportText:'',stock:{business:'',productKey:'',mechanismKey:'',audience:'',buffer:10,customRate:'',stock:{},quantities:{}}};
try{const saved=JSON.parse(localStorage.getItem('yue-stock-plan-v2')||localStorage.getItem('yue-stock-plan-v1'));if(saved){const {room,anchor,...plan}=saved;if(room||anchor)plan.audience='';Object.assign(state.stock,plan);}}catch{}
let sourceRefreshEnabled=remoteSource;
try{sourceRefreshEnabled=remoteSource?localStorage.getItem('workbench-auto-source')!=='false':cloud&&localStorage.getItem('workbench-read-source')==='true';}catch{}
const priceModule=createPriceModule({element:$('prices-view'),dialog:$('price-dialog'),icon,toast});
const titles={prices:['价格查询','产品价格查询','搜索各子表的产品报价，按规格生成提报表。'],rooms:['直播间看板','直播间数据看板','按系统分组看订单与转化，横向比较产品售卖表现。'],overview:['数据概览','产品数据概览','从产品表现到直播间转化，把每一场销售看清楚。'],products:['产品表现','每一款产品，都看得清楚','比较产品、追踪转化，查看组合装与每场直播明细。'],stock:['备货计算','产品备货计划','综合产品的全部有效历史，预测订单并拆分组件备货。'],quality:['数据与口径','数据有来处，计算有依据','查看数据覆盖、待补信息和每一个指标的计算方式。']};
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),2600);}
function updateSourceLink(){const url=state.page==='prices'?state.data?.priceCatalog?.sourceUrl:state.data?.sourceUrl;$('source-link').hidden=!url;if(url)$('source-link').href=url;}
function navigate(page){if(!titles[page])page='overview';state.page=page;updateSourceLink();$('source-refresh-link').href=`http://localhost:4318/?from=share#${page}`;history.replaceState(null,'',`#${page}`);document.querySelectorAll('[data-page]').forEach(el=>{el.classList.toggle('active',el.dataset.page===page);if(el.dataset.page===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('breadcrumb').textContent=titles[page][0];$('page-title').innerHTML=`${titles[page][1]}<span class="heading-dot">.</span>`;$('page-subtitle').textContent=titles[page][2];$('business-tabs').hidden=['stock','quality','prices'].includes(page);$('global-filters').hidden=['stock','quality','prices'].includes(page);$('range-tools').hidden=['stock','quality','prices'].includes(page);$('show-history').hidden=['stock','quality','prices'].includes(page);$('show-report').hidden=['stock','quality','prices'].includes(page);document.querySelectorAll('.page-view').forEach(n=>n.hidden=n.id!==`${page}-view`);render();if(matchMedia('(max-width:700px)').matches)requestAnimationFrame(()=>{const item=document.querySelector('.nav-item.active'),nav=item?.parentElement;if(nav&&nav.scrollWidth>nav.clientWidth)nav.scrollLeft+=item.getBoundingClientRect().left-nav.getBoundingClientRect().left-(nav.clientWidth-item.clientWidth)/2;});}
function baseRecords(ignoreDates=false){const f=state.filters;return (state.data?.records||[]).filter(r=>(!f.group||r.group===f.group)&&(!f.anchor||r.anchor===f.anchor)&&(ignoreDates||!f.from||r.date>=f.from)&&(ignoreDates||!f.to||r.date<=f.to));}
function filtered(ignoreDates=false){return baseRecords(ignoreDates).map(r=>viewRecord(r,state.filters.room)).filter(Boolean);}
function productGroups(records){const map=new Map();for(const r of records){if(!map.has(r.productKey))map.set(r.productKey,{key:r.productKey,name:r.name,bundle:r.bundle,group:r.group,records:[]});map.get(r.productKey).records.push(r);}return [...map.values()].map(p=>({...p,...summarize(p.records),latest:p.records.toSorted((a,b)=>(b.date||'').localeCompare(a.date||''))[0]}));}
function metric(label,value,note,type='box',highlight=false){return `<article class="metric metric-${type} ${highlight?'highlight':''}"><div class="metric-label">${label}</div><span class="metric-icon">${icon(type)}</span><div class="metric-value">${value}</div><div class="metric-note">${note}</div></article>`;}
function rateOf(summary){return state.rateMode==='units'?summary.unitRate:summary.rate;}
function businesses(){if(!state.data)return [];if(state.data.businesses)return state.data.businesses;return [...new Set(state.data.sheets.filter(s=>s.type==='detail').map(s=>s.group||businessName(s.title)))].map(name=>({name,...summarize(state.data.records.filter(r=>r.group===name))}));}
function populateFilters(){if(!state.data)return;const groups=businesses().map(b=>b.name);if(state.filters.group&&!groups.includes(state.filters.group))state.filters.group='';const rows=state.data.records.filter(r=>!state.filters.group||r.group===state.filters.group);const rooms=[...new Set(rows.flatMap(r=>r.rooms))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})),anchors=[...new Set(rows.map(r=>r.anchor).filter(Boolean))].sort();for(const [key,label,options] of [['group','全部业务',groups],['room','全部直播间',rooms],['anchor','全部主播',anchors]]){if(!options.includes(state.filters[key]))state.filters[key]='';$(`filter-${key}`).innerHTML=`<option value="">${label}</option>`+options.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');$(`filter-${key}`).value=state.filters[key];}}
function renderBusinessTabs(){if(!state.data)return;const rows=businesses(),all=summarize(state.data.records);$('business-tabs').innerHTML=`<button class="business-tab ${!state.filters.group?'active':''}" data-business="" ${!state.filters.group?'aria-current="true"':''}><span>全部业务</span><strong>${all.products}<small> 款产品</small></strong><em>${rows.length} 组业务 · 全部历史</em></button>`+rows.map(b=>`<button class="business-tab ${state.filters.group===b.name?'active':''} ${!b.offers?'empty':''}" data-business="${esc(b.name)}" ${state.filters.group===b.name?'aria-current="true"':''}><span>${esc(b.name)}${!b.offers?'<i>待录入</i>':''}</span><strong>${b.products}<small> 款产品</small></strong><em>${b.offers} 条售卖记录${b.pending?' · '+b.pending+' 待补':''}</em></button>`).join('');}
function sourceLink(label,query='',className=''){const url=state.data?.sourceUrl;return url?`<a class="${esc(className)}" href="${esc(query?url.split('?')[0]+query:url)}" target="_blank" rel="noreferrer">${esc(label)} ↗</a>`:`<span class="${esc(className)}">${esc(label)}</span>`;}
function sourceCoverage(){return businesses().map(b=>{const sheets=state.data.sheets.filter(s=>(s.group||businessName(s.title))===b.name);return `<div class="business-source"><div class="business-source-title"><strong>${esc(b.name)}</strong><span class="chip ${!b.offers?'pending':''}">${b.offers?`${b.products} 款产品 · ${b.offers} 条售卖`:'已接入 · 暂无售卖'}</span></div>${sheets.map(s=>`<div class="sheet-row"><div><span class="status-symbol ${s.type==='detail'&&!s.offers?'pending':''}"></span>${sourceLink(s.title,`?tab=${encodeURIComponent(s.id||'')}`)}</div><small>${s.type==='detail'?`${s.offers} 条售卖 · ${s.rows} 行组件`:s.type==='summary'?'汇总表，不重复计入':'辅助表'}</small></div>`).join('')}</div>`;}).join('');}

function setData(data){
 if(!data)return;state.data=data;if(state.stock.business&&!businesses().some(b=>b.name===state.stock.business))state.stock.business='';
 updateSourceLink();
 populateFilters();
 if(!data.products.some(p=>p.key===state.stock.productKey)&&!(state.stock.business&&businesses().some(b=>b.name===state.stock.business)&&!data.products.some(p=>p.group===state.stock.business))){
  state.stock.productKey=productGroups(data.records.filter(r=>!state.stock.business||r.group===state.stock.business)).filter(p=>p.rated>0).sort((a,b)=>b.orders-a.orders)[0]?.key||data.products.find(p=>!state.stock.business||p.group===state.stock.business)?.key||'';
  Object.assign(state.stock,{mechanismKey:'',audience:'',customRate:'',stock:{},quantities:{}});
 }
 if(state.stock.mechanismKey&&!data.records.some(r=>r.productKey===state.stock.productKey&&r.mechanismKey===state.stock.mechanismKey))Object.assign(state.stock,{mechanismKey:'',audience:'',quantities:{}});
 render();
}
function render(){renderBusinessTabs();updateRange();if(!state.data){if(state.status?.error)$(`${state.page}-view`).innerHTML=`<div class="empty-state"><h2>暂未获取到数据</h2><p>${esc(state.status.error)}</p><p class="section-note">点击右上角“刷新最新数据”重试。</p></div>`;return;}if(state.page==='overview')renderOverview();if(state.page==='rooms')renderRooms();if(state.page==='products')renderProducts();if(state.page==='stock')renderStock();if(state.page==='quality')renderQuality();if(state.page==='prices')priceModule.update(state.data.priceCatalog);}
function rateToggle(){return `<div class="segmented" aria-label="转化率口径"><button data-rate="orders" class="${state.rateMode==='orders'?'active':''}">按订单</button><button data-rate="units" class="${state.rateMode==='units'?'active':''}">按件数</button></div>`;}
function renderOverview(){const records=filtered(),s=summarize(records),pending=s.pending;
 $('overview-view').innerHTML=`<div class="metrics">${metric('在售产品',`${fmt(s.products)}<span class="unit">款</span>`,`${fmt(records.filter(r=>r.bundle).length)} 条组合装售卖记录`)}${metric('已记录订单',s.offers===s.pending&&s.offers?'—':compact(s.orders),`${fmt(s.offers-pending)} 条已填 · ${pending} 条待补单量`,'orders')}${metric('销售额估算',s.priced?`<span class="unit">¥</span>${compact(s.revenue)}`:'—','直播价 × 订单数，未扣退款','money')}${metric('加权订单峰值转化率',pct(s.rate),`按订单计算 · ${s.rated} 条有效分母`,'trend',true)}</div>
 ${pending?`<div class="hint-banner quality-strip">${icon('info')}<span>有 ${pending} 条售卖记录尚未填齐单量，已从转化率计算中排除。部分合计空白已按完整系统数据重算。</span><button data-go="quality">查看数据</button></div>`:`<div class="hint-banner">${icon('layers')}<span>组合装按一单统计订单和销售额。备货按每单包含的组件分别计算。</span><button data-go="stock">去备货 ${icon('arrow')}</button></div>`}
 <div class="charts-grid"><article class="panel"><div class="panel-header"><div><h2>销售与转化趋势</h2><p>按直播日期观察订单与订单峰值转化率</p></div><span class="chip">${records.length?'当前筛选范围':'暂无数据'}</span></div><div class="chart-legend"><span><i class="legend-square"></i>订单数</span><span><i class="legend-line"></i>订单峰值转化率</span></div>${trendChart(records)}<div class="panel-footnote">转化率使用有完整单量及有效峰值的记录；缺失数据以空缺显示。</div></article>
 <article class="panel"><div class="panel-header"><div><h2>直播间转化表现</h2><p>订单数 / 产品售卖记录的峰值在线人数</p></div>${icon('trend')}</div>${roomChart()}<div class="panel-footnote">各直播间的售卖产品不同，此处反映所售产品组合的表现。</div></article></div>
 ${insightStrip(records)}${productTable(records,true)}<p class="section-note">峰值转化率衡量订单或件数相对峰值在线的比例；原表没有去重购买人数和累计观看人数，因此不能据此计算用户购买转化率。</p>`;
}
function trendChart(records){const dates=[...new Set(records.map(r=>r.date).filter(Boolean))].sort();if(!dates.length)return '<div class="chart-empty">当前筛选范围没有直播记录</div>';
 const points=dates.map(date=>({date,...summarize(records.filter(r=>r.date===date))}));
 const width=620,height=225,left=40,right=45,top=20,bottom=32,w=width-left-right,h=height-top-bottom,maxO=Math.max(...points.map(p=>p.orders),1)*1.15,maxR=Math.max(...points.map(p=>p.rate||0),.01)*1.15,step=w/points.length;
 const yO=v=>top+h-v/maxO*h,yR=v=>top+h-v/maxR*h,x=i=>left+step*(i+.5);
 const lines=[0,.5,1].map(n=>{const y=top+h-h*n;return `<line x1="${left}" y1="${y}" x2="${width-right}" y2="${y}" stroke="var(--line)" stroke-dasharray="3 4"/><text x="${left-8}" y="${y+3}" text-anchor="end">${maxO*n>=10000?fmt(maxO*n/10000,1)+'万':fmt(maxO*n)}</text><text x="${width-right+8}" y="${y+3}">${fmt(maxR*n*100,1)}%</text>`;}).join('');
 const bars=points.map((p,i)=>`<rect x="${x(i)-Math.min(step*.22,20)}" y="${yO(p.orders)}" width="${Math.min(step*.44,40)}" height="${top+h-yO(p.orders)}" rx="5" fill="url(#order-bars)"><title>${p.date}：${fmt(p.orders)} 单${p.pending?'，另有待补单量':''}</title></rect><text x="${x(i)}" y="${height-8}" text-anchor="middle">${p.date.slice(5).replace('-','/')}</text>`).join('');
 let path='',prev=false;points.forEach((p,i)=>{if(p.rate!==null){path+=`${prev?'L':'M'}${x(i)},${yR(p.rate)} `;prev=true;}else prev=false;});
 const dots=points.map((p,i)=>p.rate===null?'':`<circle cx="${x(i)}" cy="${yR(p.rate)}" r="3.4" fill="var(--paper)" stroke="var(--chart-line)" stroke-width="2"><title>${p.date}：${pct(p.rate)}</title></circle>`).join('');
 return `<svg class="trend-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="每日订单量与订单峰值转化率趋势"><defs><linearGradient id="order-bars" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--chart-bar)"/><stop offset="100%" stop-color="var(--chart-bar-end)"/></linearGradient></defs>${lines}${bars}<path d="${path}" fill="none" stroke="var(--chart-line)" stroke-width="2" stroke-linejoin="round"/>${dots}</svg>`;
}
function roomChart(){const f=state.filters,base=state.data.records.filter(r=>(!f.group||r.group===f.group)&&(!f.anchor||r.anchor===f.anchor)&&(!f.from||r.date>=f.from)&&(!f.to||r.date<=f.to));const rows=state.data.rooms.filter(room=>!f.room||room===f.room).map(room=>({room,...summarize(base.map(r=>viewRecord(r,room)).filter(Boolean))})).filter(r=>r.rated).sort((a,b)=>b.rate-a.rate).slice(0,6);const max=Math.max(...rows.map(r=>r.rate),.01);return rows.length?`<div class="room-bars">${rows.map(r=>`<div class="room-bar-row" style="--room-color:var(--room-${esc(r.room[0].toLowerCase())},var(--blue))"><span>${esc(r.room)}</span><div class="room-bar-bg"><div class="room-bar-fill" style="width:${r.rate/max*100}%"></div></div><strong title="${fmt(r.orders)} 单 / ${r.rated} 条有效记录">${pct(r.rate)}</strong></div>`).join('')}</div>`:'<div class="chart-empty">暂无有效的直播间转化数据</div>';}
function sortedProducts(records){let rows=productGroups(records);if(state.search){const q=state.search.toLowerCase();rows=rows.filter(p=>(p.name+' '+p.latest.components.map(c=>c.name).join(' ')).toLowerCase().includes(q));}return rows.sort((a,b)=>state.sort==='rate'?(rateOf(b)??-1)-(rateOf(a)??-1):state.sort==='revenue'?b.revenue-a.revenue:b.orders-a.orders);}
function productTable(records,overview=false){const rows=sortedProducts(records),pageSize=overview?6:12,page=overview?1:Math.min(state.tablePage,Math.max(1,Math.ceil(rows.length/pageSize))),show=rows.slice((page-1)*pageSize,page*pageSize),maxRate=Math.max(...rows.map(p=>rateOf(p)||0),.01);state.tablePage=page;
 return `<article class="panel table-panel"><div class="panel-header"><div><h2>${overview?'产品表现排行':'产品表现明细'}</h2><p>同一组合只计一笔订单，点击产品查看场次和组件</p></div><div class="table-toolbar">${overview?`<button class="action-link" data-go="products">查看全部产品 ${icon('arrow')}</button>`:`<div class="search-wrap">${icon('search')}<input id="product-search" placeholder="搜索产品或组合组件…" value="${esc(state.search)}" aria-label="搜索产品"></div><button class="button outline small" id="export-products">${icon('download')} 导出数据</button>`}${rateToggle()}<select id="product-sort" class="sort-select" aria-label="产品排序"><option value="orders" ${state.sort==='orders'?'selected':''}>按订单排序</option><option value="rate" ${state.sort==='rate'?'selected':''}>按转化率排序</option><option value="revenue" ${state.sort==='revenue'?'selected':''}>按销售额排序</option></select></div></div>
 <div class="table-scroll"><table><thead><tr><th>产品名称</th><th>售卖记录</th><th class="num">已知订单</th><th class="num">销售额估算</th><th class="num">${state.rateMode==='orders'?'订单':'件数'}峰值转化率</th><th class="num">操作</th></tr></thead><tbody>${show.map((p,i)=>`<tr class="click-row" data-product="${esc(p.key)}"><td><div class="product-cell"><div><strong>${esc(p.name)} ${p.bundle?'<span class="chip bundle">组合品</span>':''}</strong><small>${p.bundle?esc(p.latest.mechanism):`${esc(p.group)} · ${esc(p.latest.supplier||'提报主体待填')}`}</small></div></div></td><td>${p.offers}<span class="text-muted"> 次</span>${p.pending?` <span class="chip pending">${p.pending} 待补</span>`:''}</td><td class="num">${p.offers===p.pending?'—':fmt(p.orders)}</td><td class="num">${p.priced?money(p.revenue):'—'}</td><td class="num"><div class="rate-cell"><span class="rate-track"><i style="width:${Math.max(0,(rateOf(p)||0)/maxRate*100)}%"></i></span><span class="rate-value">${pct(rateOf(p))}</span></div></td><td class="num"><button class="detail-link" data-plan="${esc(p.key)}">算备货 ${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="no-results">没有匹配的产品，请调整筛选条件。</td></tr>'}</tbody></table></div>
 <div class="table-footer"><span>共 ${rows.length} 款产品${overview?`，展示前 ${Math.min(rows.length,pageSize)} 款`:''} · 转化率按完整记录的分子、分母加权计算</span>${!overview?`<div class="pager"><button id="prev-page" ${page<=1?'disabled':''} aria-label="上一页">‹</button><span>${page} / ${Math.max(1,Math.ceil(rows.length/pageSize))}</span><button id="next-page" ${page>=Math.ceil(rows.length/pageSize)?'disabled':''} aria-label="下一页">›</button></div>`:''}</div></article>`;
}
function renderProducts(){$('products-view').innerHTML=productTable(filtered())+`<p class="section-note">${state.rateMode==='orders'?'订单峰值转化率 = 订单数 / 峰值在线人数。组合装的所有组件共用一笔订单。':'件数峰值转化率 = 发货件数 / 峰值在线人数；组合装为全部组件的件数之和。各组件的原表转换率可在详情查看。'} 缺失分母或待补单量不计入加权率。</p>`;}
function planFor(key){showProduct.roomGroup=null;state.stock.business=state.data.products.find(p=>p.key===key)?.group||state.stock.business;state.stock.productKey=key;state.stock.mechanismKey='';state.stock.audience='';state.stock.customRate='';state.stock.stock={};state.stock.quantities={};navigate('stock');$('product-dialog').close();window.scrollTo({top:0,behavior:'smooth'});}
function showProduct(key){const boardKey=state.page==='rooms'?showProduct.roomGroup:null;const rows=(boardKey?roomGroups(baseRecords(),state.filters.room).find(g=>g.key===boardKey)?.records||[]:filtered()).filter(r=>r.productKey===key);if(!rows.length)return;const p=rows[0],s=summarize(rows),latest=rows.toSorted((a,b)=>(b.date||'').localeCompare(a.date||''))[0];
 $('dialog-content').innerHTML=`<div class="dialog-head"><div><h2>${esc(p.name)} ${p.bundle?'<span class="chip bundle">组合品</span>':''}</h2><p>${esc(p.group)} · ${esc(state.filters.room||(boardKey?boardKey+' 组直播间':'全部直播间'))} · 当前筛选范围</p></div><button class="dialog-close" id="close-dialog" aria-label="关闭">×</button></div><div class="dialog-body"><div class="metrics">${metric('售卖记录',fmt(rows.length),'每条对应一次产品售卖')}${metric('已知订单',s.offers===s.pending?'—':fmt(s.orders),'组合组件不重复计单','orders')}${metric('销售额估算',s.priced?money(s.revenue):'—','直播价 × 订单数','money')}${metric('订单峰值转化率',pct(s.rate),'完整记录加权计算','trend',true)}</div>
 ${p.bundle?`<div class="bundle-info"><strong>这是一件组合品，组件一起售卖</strong>${esc(latest.mechanism)}<br>每笔订单计 1 单；各组件备货分别乘以对应的每单发货数量。</div>`:''}
 <div class="dialog-section"><h3>直播售卖记录</h3><div class="table-scroll"><table><thead><tr><th>日期 / 主播</th><th>直播间</th><th class="num">价格</th><th class="num">订单</th><th class="num">峰值在线</th><th class="num">订单转化率</th><th>数据状态</th></tr></thead><tbody>${rows.toSorted((a,b)=>(b.date||'').localeCompare(a.date||'')).map(r=>`<tr><td>${esc(r.date||'日期待填')}<br><small class="text-muted">${esc(r.time)} · ${esc(r.anchor)}</small></td><td>${esc(state.filters.room||r.displayRoom||r.rooms.join('、'))}</td><td class="num">${money(r.price)}</td><td class="num">${fmt(r.orders)}</td><td class="num">${fmt(r.peak)}</td><td class="num">${pct(r.rate)}</td><td>${r.pending?'<span class="chip pending">待补单量</span>':r.derived?'<span class="chip derived">系统数据重算</span>':'已填'} ${r.issues.some(x=>x.kind==='warning')?'<span class="chip pending">有待核对项</span>':''}<br>${sourceLink(`原表第 ${r.row} 行`,`?tab=${encodeURIComponent(r.sheetId)}&range=A${r.row}:N${r.row}`,'detail-link')}</td></tr>`).join('')}</tbody></table></div></div>
 <div class="dialog-section"><h3>组件件数与原表件数转换率</h3><div class="table-scroll"><table><thead><tr><th>日期 / 组件</th><th class="num">每单发货</th><th class="num">发货件数</th><th class="num">件数 / 峰值</th><th class="num">原表转换率</th></tr></thead><tbody>${rows.flatMap(r=>r.components.map(c=>`<tr><td>${esc(c.name)}<br><small class="text-muted">${esc(r.date)} · ${esc(c.supplier||'厂家待填')} · 原表第 ${c.row} 行</small></td><td class="num">${fmt(c.quantity)}</td><td class="num">${fmt(c.units)}</td><td class="num">${pct(c.units!==null&&r.peak>0?c.units/r.peak:null)}</td><td class="num">${state.filters.room?'—':pct(c.sourceRate)}</td></tr>`)).join('')}</tbody></table></div></div>${rows.flatMap(r=>r.issues).length?`<div class="dialog-section"><h3>需要留意的数据</h3>${rows.flatMap(r=>r.issues).map(i=>`<p class="section-note">第 ${i.row} 行：${esc(i.message)}</p>`).join('')}</div>`:''}<div class="dialog-actions"><button class="button outline" id="close-dialog-bottom">关闭</button><button class="button primary" data-plan="${esc(key)}">${icon('calculator')} 计算这个产品的备货</button></div></div>`;
 $('product-dialog').showModal();
}

function stockInput(){const s=state.stock;return {...s,audience:s.audience===''?null:Number(s.audience),customRate:s.customRate===''?null:Number(s.customRate)/100};}
function savePlan(){try{localStorage.setItem('yue-stock-plan-v2',JSON.stringify(state.stock));}catch{}}
function stockOptions(){const s=state.stock;return [...new Map(state.data.records.filter(r=>r.productKey===s.productKey).map(r=>[r.mechanismKey,r])).values()];}
let disposeStockPicker=()=>{},restoringStockPickerFocus=false;
function setupStockPicker(choices){
 const root=$('stock-product-picker'),input=$('stock-product'),toggle=$('stock-product-toggle'),menu=$('stock-product-menu'),list=$('stock-product-list'),status=$('stock-product-count');
 const controller=new AbortController(),signal=controller.signal;
 const selected=choices.find(p=>p.key===state.stock.productKey),selectedName=selected?.name||'';
 let matches=[],active=-1,composing=false;
 const on=(target,type,listener,options={})=>target.addEventListener(type,listener,{...options,signal});
 function position(){
  if(menu.hidden)return;
  const rect=root.getBoundingClientRect(),viewport=window.visualViewport,viewportTop=viewport?.offsetTop||0;
  const top=Math.max(viewportTop,document.querySelector('.sidebar').getBoundingClientRect().bottom),bottom=viewportTop+(viewport?.height||innerHeight);
  const below=bottom-rect.bottom-12,above=rect.top-top-12,up=below<160&&above>below;
  root.dataset.side=up?'above':'below';
  menu.style.maxHeight=`${Math.max(80,Math.min(300,up?above:below))}px`;
 }
 function highlight(index,scroll=false){
  active=index;
  for(const [i,option] of [...list.children].entries())option.classList.toggle('is-active',i===active);
  const option=list.children[active];
  if(option){input.setAttribute('aria-activedescendant',option.id);if(scroll)option.scrollIntoView({block:'nearest'});}
  else input.removeAttribute('aria-activedescendant');
 }
 function close(restore=true){
  menu.hidden=true;input.setAttribute('aria-expanded','false');toggle.setAttribute('aria-expanded','false');highlight(-1);
  if(restore)input.value=selectedName;
 }
 function open(query=''){
  if(input.disabled)return;
  const words=query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
  matches=choices.filter(p=>words.every(word=>`${p.name} ${p.group}`.toLocaleLowerCase().includes(word)));
  status.textContent=words.length?`找到 ${matches.length} 款产品`:`共 ${matches.length} 款产品 · 输入关键词搜索`;
  list.innerHTML=matches.map((p,i)=>`<li id="stock-product-option-${i}" role="option" aria-selected="${p.key===state.stock.productKey}" data-choice="${i}"><span class="stock-product-name">${esc(p.name)}</span>${p.bundle?'<span class="chip bundle">组合品</span>':''}${p.key===state.stock.productKey?icon('check'):''}</li>`).join('');
  $('stock-product-empty').hidden=matches.length>0;
  menu.hidden=false;input.setAttribute('aria-expanded','true');toggle.setAttribute('aria-expanded','true');highlight(-1);menu.scrollTop=0;position();
 }
 function choose(product){
  if(!product)return;
  close();
  if(product.key===state.stock.productKey){input.value=product.name;return;}
  // Only a confirmed choice changes the plan; typing never changes its history.
  const keyboard=document.activeElement===input;
  planFor(product.key);
  if(keyboard){restoringStockPickerFocus=true;$('stock-product').focus({preventScroll:true});restoringStockPickerFocus=false;}
 }
 on(input,'focus',()=>{if(!restoringStockPickerFocus){open();input.select();}});
 on(input,'click',()=>{if(menu.hidden)open();});
 on(input,'input',event=>{if(!composing&&!event.isComposing)open(input.value);});
 on(input,'compositionstart',()=>{composing=true;});
 on(input,'compositionend',()=>{composing=false;open(input.value);});
 on(input,'change',()=>{
  if(composing)return;
  const exact=choices.filter(p=>p.name===input.value.trim());
  if(exact.length===1)choose(exact[0]);
 });
 on(input,'keydown',event=>{
  if(composing||event.isComposing||event.keyCode===229)return;
  if(event.key==='ArrowDown'||event.key==='ArrowUp'){
   event.preventDefault();if(menu.hidden)open();
   if(matches.length)highlight((active+(event.key==='ArrowDown'?1:active<0?0:-1)+matches.length)%matches.length,true);
  }else if(event.key==='Enter'&&!menu.hidden){
   event.preventDefault();const exact=matches.filter(p=>p.name===input.value.trim());
   choose(matches[active]||(exact.length===1?exact[0]:matches.length===1?matches[0]:null));
  }else if(event.key==='Escape'){event.preventDefault();close();}
 });
 on(toggle,'pointerdown',event=>event.preventDefault());
 on(toggle,'click',()=>{if(menu.hidden)open();else close();});
 // Keep input focus while tapping an option, so blur cannot replace the list
 // before the click. Native touch scrolling remains available in the menu.
 on(list,'pointerdown',event=>{if(event.target.closest('[data-choice]'))event.preventDefault();});
 on(list,'click',event=>{const option=event.target.closest('[data-choice]');if(option)choose(matches[Number(option.dataset.choice)]);});
 on(list,'pointermove',event=>{if(event.pointerType==='mouse'){const option=event.target.closest('[data-choice]');if(option)highlight(Number(option.dataset.choice));}});
 on(root,'focusout',event=>{if(!root.contains(event.relatedTarget))close();});
 on(document,'pointerdown',event=>{if(!root.contains(event.target))close();});
 on(window,'resize',position);on(window,'scroll',position,{passive:true});
 if(window.visualViewport){on(window.visualViewport,'resize',position);on(window.visualViewport,'scroll',position);}
 return ()=>controller.abort();
}
function renderStock(){disposeStockPicker();const s=state.stock,options=stockOptions();let result=predict(state.data,stockInput());if(result.mechanismKey&&!s.mechanismKey)s.mechanismKey=result.mechanismKey;
 const selected=state.data.products.find(p=>p.key===s.productKey);if(selected)s.business=selected.group;const choices=state.data.products.filter(p=>!s.business||p.group===s.business);
 $('stock-view').innerHTML=`<div class="stock-grid"><article class="panel form-panel"><h2>本次备货设置</h2><p class="form-intro">先选业务和产品，再综合该产品全部有效历史备货</p><label class="field"><span>所属业务</span><select id="stock-business">${businesses().map(b=>`<option value="${esc(b.name)}" ${s.business===b.name?'selected':''}>${esc(b.name)} · ${b.products} 款产品</option>`).join('')}</select><small>选择产品所在业务；预测仍覆盖该产品全部直播间的历史。</small></label>${!choices.length?`<div class="empty-business-note">${esc(s.business)} 的明细表已接入，暂无售卖产品。原表填入后刷新即可计算。</div>`:''}<div class="stock-fields"><div class="field stock-product-field"><label for="stock-product">产品 / 组合品</label><div id="stock-product-picker" class="stock-product-picker"><input type="text" id="stock-product" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="stock-product-list" aria-describedby="stock-product-help" value="${esc(selected?.name||'')}" placeholder="${choices.length?'输入关键词或下拉选择':'该业务暂无产品'}" ${!choices.length?'disabled':''} autocomplete="off" autocapitalize="off" spellcheck="false" enterkeyhint="done"><button type="button" id="stock-product-toggle" class="stock-product-toggle" aria-label="展开产品列表" aria-controls="stock-product-list" aria-expanded="false" tabindex="-1" ${!choices.length?'disabled':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg></button><div id="stock-product-menu" class="stock-product-menu" hidden><div id="stock-product-count" class="stock-product-count" role="status" aria-live="polite"></div><ul id="stock-product-list" role="listbox" aria-label="选择产品或组合品"></ul><div id="stock-product-empty" class="stock-product-empty" hidden>未找到匹配产品，请换个关键词。</div></div></div><small id="stock-product-help">可下拉选择或输入搜索；组合品按整单预测，再分别计算组件。</small></div><label class="field"><span>本次售卖规格</span><select id="stock-mechanism">${options.map(r=>`<option value="${esc(r.mechanismKey)}" ${s.mechanismKey===r.mechanismKey?'selected':''}>${esc(r.mechanism)}</option>`).join('')}</select><small>用于确定本次每单发货数量；历史计算覆盖该产品的全部规格。</small></label></div><div class="history-scope"><div class="scope-title">${icon('database')} 全部历史参与计算</div><p>${result.recordCount||0} 条有效记录，覆盖 ${result.roomCount||0} 个直播间、${result.anchorCount||0} 位主播。</p><small>${result.dateRange?.from?`${esc(result.dateRange.from)} 至 ${esc(result.dateRange.to)}`:'等待完整历史数据'}</small></div><div id="stock-bundle-note">${selected?.bundle?`<div class="bundle-info"><strong>${icon('layers')} 组合明细</strong>${esc(result.mechanism||'')}</div>`:''}</div><div class="form-divider"></div><div class="two-fields"><label class="field"><span>预计峰值在线人数</span><div class="input-suffix"><input type="number" min="1" step="1" id="stock-audience" value="${esc(s.audience)}" placeholder="${result.suggestedAudience?Math.round(result.suggestedAudience):'请输入'}"><span>人</span></div><small id="audience-hint">${result.suggestedAudience?`留空使用历史场次中位数 ${fmt(result.suggestedAudience)} 人`:'暂无历史人数，请手动填写。'}</small></label><label class="field"><span>安全余量</span><div class="input-suffix"><input type="number" min="0" max="200" step="1" id="stock-buffer" value="${esc(s.buffer)}"><span>%</span></div><small>默认 10%，可根据备货习惯调整。</small></label></div><label class="field"><details ${s.customRate!==''||!result.baseline?.sufficient?'open':''}><summary>${result.baseline?.sufficient?'手动指定转化率（可选）':'样本不足，请手动确认转化率'}</summary><div class="input-suffix"><input type="number" min="0" step="0.01" id="stock-custom-rate" value="${esc(s.customRate)}" placeholder="满 3 场后可使用稳健平均"><span>%</span></div><small>不足 3 场不会自动生成备货量。请核实后输入；手动值会覆盖历史均值，并标明“手动假设”。</small></details></label><div class="formula">预计订单 = 峰值在线人数 × 历史稳健平均转化率<br>手动指定时，采用已确认的手动转化率<br>组件备货 = 向上取整（预计订单 × 每单数量 × 安全系数）<br>需补备货 = 组件备货 − 可用库存，最低为 0</div><button id="stock-reset" class="button quiet small">重置本次输入</button></article><div id="stock-right" class="stock-right"></div></div><p class="section-note">备货基于历史售卖表现；主播、价格和流量结构变化会影响实际结果。全部有效历史先参与评估，再去掉两端极值计算场均转化率；手动输入时采用手动值。输入本次预计在线人数，按本次每单数量拆分备货。 每单数量和可用库存可在组件表中直接修改。</p>`;
 disposeStockPicker=setupStockPicker(choices);renderStockResult(result);savePlan();
}
function baselineRoleLabel(role){return {'included':'计入均值','trimmed-low':'低位去尾','trimmed-high':'高位去尾','insufficient':'仅供参考'}[role]||'仅供参考';}
function stockBaselineInfo(result){const b=result.baseline;if(!b)return '';
 return `<article class="panel baseline-panel"><div class="panel-header"><div><h2>备货转化率怎么算</h2><p>先逐场计算，再去掉两端极值，剩余场次等权平均</p></div><span class="sample-tag">${b.sufficient?'历史稳健平均':'样本不足'}</span></div><div class="baseline-metrics"><div><small>历史稳健平均</small><strong>${pct(result.historicalRate)}</strong></div><div><small>未去尾的场均值 · 参考</small><strong>${pct(b.rawMeanRate)}</strong></div><div><small>计入均值 / 全部有效场次</small><strong>${b.usedCount} <em>/ ${result.samples.length} 场</em></strong></div></div><p class="baseline-rule">${b.sufficient?`最高、最低各去掉 ${b.trimEachSide} 场，共 ${b.trimmedCount} 场；剩余 ${b.usedCount} 场取平均。${result.samples.length<5?' 当前仅 3–4 场历史，中间样本较少，备货前请复核。':''}`:`当前 ${result.samples.length} 场，少于 3 场，历史场均值仅供参考，暂不作为自动备货依据。`}</p><p class="baseline-rule">规则：按该产品全部历史场次转化率排序，两端各去掉 20%（场数向下取整，每端至少 1 场）。同日期、时间、主播的多条记录合并为一场；覆盖全部直播间和规格。去尾不代表原始销售数据有误。</p>${result.customRate?'<p class="baseline-warning">本次使用手动假设；上方历史均值仅供比较，不参与当前订单预测。</p>':!b.sufficient?'<p class="baseline-warning">单场爆单无法仅靠这场数据识别。补足历史，或在左侧输入经确认的转化率后，才生成备货量。</p>':''}</article>`;
}
function renderStockResult(result=predict(state.data,stockInput())){const s=state.stock,latest=state.data.records.find(r=>r.productKey===s.productKey&&r.mechanismKey===s.mechanismKey);
 const components=result.components||latest?.components.map(c=>({name:c.name,supplier:c.supplier,quantity:s.quantities[c.name]??c.quantity,stock:s.stock[c.name]??0,demand:null,target:null,purchase:null}))||[];
 $('stock-right').innerHTML=`${result.error?`<div class="sample-empty" role="status"><strong>${result.baseline&&!result.baseline.sufficient?'历史不足，请确认转化率':'还需要一点信息'}</strong><p>${esc(result.error)}</p></div>`:`<article class="stock-result"><div class="eyebrow">NEXT LIVE · STOCK PLAN</div><div class="result-label">预计售卖订单${result.customRate?' · 手动假设':' · 历史稳健平均'}</div><div class="result-value">${fmt(result.expectedOrders)}<small>单</small></div><div class="result-stats"><div><small>${result.customRate?'手动转化率':'历史稳健平均转化率'}</small><strong>${pct(result.rate)}</strong></div><div><small>预计峰值在线</small><strong>${fmt(result.audience)} <small style="display:inline">人</small></strong></div><div><small>安全余量</small><strong>+${fmt(result.buffer)}%</strong></div></div><p class="result-subtitle">${result.customRate?'本次使用手动输入的转化率，请确认其合理性。':result.lowerOrders!==null?`保留场次的转化率上下沿对应约 ${fmt(result.lowerOrders)}–${fmt(result.upperOrders)} 单，不含安全余量；这是波动参考，并非置信区间。`:'去尾后仅保留 1 场，无法提供波动范围，请谨慎参考。'}</p></article>`}
 ${stockBaselineInfo(result)}
 <article class="panel table-panel stock-components"><div class="panel-header"><div><h2>${latest?.bundle?'组合组件备货清单':'产品备货清单'}</h2><p>每单发货数、可用库存均可编辑</p></div><button id="export-stock" class="button outline small" ${result.error?'disabled':''}>${icon('download')} 导出</button></div><div class="table-scroll"><table><thead><tr><th>组件名称</th><th class="num">每单数量</th><th class="num">建议备货</th><th class="num">可用库存</th><th class="num">需补备货</th></tr></thead><tbody>${components.map((c,i)=>`<tr><td>${esc(c.name)}${c.supplier?`<small class="component-supplier">${esc(c.supplier)}</small>`:''}</td><td class="num" data-label="每单数量"><input class="inline-number" data-quantity="${i}" aria-label="${esc(c.name)}每单数量" type="number" min="1" step="1" value="${esc(s.quantities[c.name]??c.quantity)}"></td><td class="num" data-label="建议备货（含余量）">${fmt(c.target)}<small class="text-muted"> 件</small></td><td class="num" data-label="可用库存"><input class="inline-number" data-stock="${i}" aria-label="${esc(c.name)}可用库存" type="number" min="0" step="1" value="${esc(s.stock[c.name]??0)}"></td><td class="num purchase" data-label="需补备货">${fmt(c.purchase)}<small class="text-muted"> 件</small></td></tr>`).join('')}</tbody></table></div><p class="mini-note">建议备货已包含安全余量；每个组件分别减去现有库存。${result.customRate?'订单预测采用本次手动转化率。':'订单预测采用全部历史场次去尾后的等权平均转化率。'}</p></article>
 <article class="panel"><div class="panel-header"><div><h2>全部历史计算依据</h2><p>${result.recordCount||0} 条有效售卖记录 · ${result.samples?.length||0} 场直播 · ${result.roomCount||0} 个直播间</p></div><span class="sample-tag">${result.customRate?'手动假设':result.baseline?.sufficient?'去尾后等权平均':'仅供参考'}</span></div>${result.samples?.length?'<div class="sample-list">'+result.samples.map(r=>`<div class="sample-row" data-baseline-role="${r.baselineRole}"><div>${esc(r.date)} <span class="text-muted">${esc(r.time)} · ${esc(r.anchor)}</span><small>${esc(r.rooms?.join('、')||'直播间待填')} · ${fmt(r.orders)} 单 / 对应峰值合计 ${fmt(r.peak)} 人</small></div><div class="sample-rate"><strong>${pct(r.rate)}</strong><span class="baseline-role">${baselineRoleLabel(r.baselineRole)}</span></div></div>`).join('')+'</div>':'<p class="section-note">该产品暂无完整的历史订单和峰值记录。</p>'}<div class="panel-footnote">${result.baseline?.rawMeanRate!==null&&result.baseline?.rawMeanRate!==undefined?`未去尾的场均转化率 ${pct(result.baseline.rawMeanRate)}，${result.historicalRate!==null?`稳健平均 ${pct(result.historicalRate)}`:'样本不足，未启用自动备货'}。`:''} ${result.excluded?`${result.excluded} 条记录因缺失数据或单量冲突而未参与评估。`:''} 待补单量和无效峰值不参与预测。高位、低位去尾仅影响备货均值；销售统计保留全部有效数据。</div></article>`;
 // Preserve keyboard editing without replacing the focused input on each keystroke.
 savePlan();
}
function renderQuality(){const d=state.data,warning=d.issues.filter(i=>i.kind==='warning'),pending=d.records.filter(r=>r.pending).length,derived=d.records.filter(r=>r.derived).length;
 $('quality-view').innerHTML=`<div class="metrics">${metric('实际售卖记录',fmt(d.records.length),'组合品已合并为一条记录','orders')}${metric('待补单量',fmt(pending),'不把缺失数据当作零销量','database')}${metric('已重算合计',fmt(derived),'由完整各系统数据重新计算','calculator')}${metric('需要核对',fmt(warning.length),'保留原始差异与对应行号','info')}</div><div class="quality-grid"><article class="panel"><div class="panel-header"><div><h2>数据来源与覆盖</h2><p>${esc(d.name)} · ${time(d.fetchedAt)} 成功读取</p></div>${d.sourceUrl?sourceLink('打开原表','','action-link'):''}</div>${sourceCoverage()}<p class="section-note">每次打开页面自动读取一次，右上角也可手动刷新。只有全部工作表读取成功后才更新数据；失败时保留上次成功快照并显示失败状态。</p></article><article class="panel"><h2>产品与组合品</h2><div class="definition"><strong>合并行中的组件一起售卖</strong><p>同一售卖记录下，日期、主播、系统和组合价合并的后续产品，作为同一组合的组件。组件可以来自不同提报主体，厂家信息分别保留。订单、价格、销售额按组合主行计一次。</p><div class="example">百年堂阿胶块 ×1 + 打粉机 ×1 + 黑芝麻阿胶糕 ×6<br>399 元 / 单；卖 100 单，对应备货 100、100、600 件。</div></div><div class="definition"><strong>单品与不同规格</strong><p>同名产品的不同拍发规格分别保留。备货综合同一产品全部规格的历史订单和对应峰值计算。本次选择的规格及每单发货数量，单独用于组件备货拆分。</p></div></article></div><article class="panel" style="margin-bottom:23px"><h2>指标计算口径</h2><div class="definition"><strong>订单峰值转化率</strong><p>订单数 ÷ 峰值在线人数。组合品为组合订单，不累计组件订单。汇总使用有效记录的订单合计 ÷ 对应峰值合计，不能理解为去重用户购买率；同一观众可能跨产品重复出现。</p></div><div class="definition"><strong>件数峰值转化率与原表</strong><p>原表“峰值转换率”为每个组件的最小颗粒度件数 ÷ 峰值在线人数。网站按件数查看组合时，使用各组件件数合计；各组件原表数值在产品详情中保留。这一比例可能大于 100%。</p></div><div class="definition"><strong>订单、销售额与缺失值</strong><p>优先使用原表合计单量。合计未填但所有直播间单量均完整时重算，并明确标记。单量未填时忽略公式生成的零件数。销售额估算 = 订单 × 直播价，未扣退款、运费或费用；不是实收金额。</p></div><div class="definition"><strong>备货量</strong><p>取该产品的全部有效历史记录，覆盖全部直播间、主播、日期和售卖规格，先合并同日期、时间、主播的记录，逐场计算订单数 ÷ 对应峰值合计，再对各场转化率去掉两端极值后等权平均。去掉最高、最低各 20%（场数向下取整、每端至少 1 场），至少 3 场才启用自动备货；3–4 场仅保留中间 1–2 场，参考较弱。被去尾的场次仍保留原始销售数据。人数留空使用历史峰值中位数，安全余量默认 10%，库存默认 0；这些输入均可修改。按每个组件单独向上取整，并扣减可用库存。不足 3 场时需手动确认转化率，无人数历史时也需输入人数。</p></div></article><article class="panel table-panel"><div class="panel-header"><div><h2>数据待补与核对明细</h2><p>直接定位原表，网站不会修改源文档</p></div><span class="quality-count">${d.issues.length} 条信息</span></div><div class="table-scroll"><table><thead><tr><th>产品</th><th>原表位置</th><th>类型</th><th>说明</th></tr></thead><tbody>${d.issues.map(i=>`<tr><td>${esc(i.product)}</td><td>${esc(i.sheet)} · 第 ${i.row} 行</td><td><span class="chip ${i.kind==='pending'?'pending':i.kind==='derived'?'derived':'pending'}">${i.kind==='pending'?'待补':i.kind==='derived'?'已重算':'待核对'}</span></td><td class="issue-text">${esc(i.message)}</td></tr>`).join('')||'<tr><td colspan="4" class="no-results">没有发现待补或待核对信息</td></tr>'}</tbody></table></div></article>`;
}

function csvDownload(filename,rows){const cell=v=>{const text=String(v??'');const safe=/^[=+@\-\t\r]/.test(text)?`'${text}`:text;return `"${safe.replace(/"/g,'""')}"`;};const content='\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportProducts(){const rows=sortedProducts(filtered());csvDownload('产品表现.csv',[['业务','产品','是否组合','组件规格（最近一次）','售卖记录数','待补单量记录','已知订单','销售额估算','订单峰值转化率','件数峰值转化率','数据更新时间'],...rows.map(p=>[p.group,p.name,p.bundle?'是':'否',p.latest.mechanism,p.offers,p.pending,p.offers===p.pending?'':p.orders,p.priced?p.revenue:'',pct(p.rate),pct(p.unitRate),time(state.data.fetchedAt)])]);toast('已导出当前筛选的产品数据');}
function exportStock(){const r=predict(state.data,stockInput());if(r.error)return;csvDownload(`${r.product.name}备货清单.csv`,[['产品',r.product.name],['计算范围','该产品全部有效历史（全部直播间、主播、规格）'],['本次售卖规格',r.mechanism],['预计峰值在线',r.audience],['本次采用转化率',pct(r.rate)],['转化率来源',r.customRate?'手动假设':'历史稳健平均（去尾后按场次等权）'],['历史稳健平均转化率',pct(r.historicalRate)],['未去尾的场均转化率（仅供参考）',pct(r.baseline.rawMeanRate)],['去尾规则','两端各20%向下取整，每端至少1场；不足3场需手动确认'],['有效售卖记录数',r.recordCount],['有效历史场次',r.samples.length],['计入历史均值场次',r.baseline.usedCount],['高低位去尾总场次',r.baseline.trimmedCount],['覆盖直播间数',r.roomCount],['预计订单',r.expectedOrders],['安全余量',`${r.buffer}%`],['源数据时间',time(state.data.fetchedAt)],[],['组件','提报主体','每单数量','需求件数','含余量建议备货','可用库存','需补备货'],...r.components.map(c=>[c.name,c.supplier||'',c.quantity,c.demand,c.target,c.stock,c.purchase]),[],['历史日期','时间','主播','直播间','订单','对应峰值合计','单场转化率','历史均值处理'],...r.samples.map(s=>[s.date,s.time,s.anchor,s.rooms.join('、'),s.orders,s.peak,pct(s.rate),baselineRoleLabel(s.baselineRole)])]);toast('已导出组件备货清单及计算依据');}

function rangeDescription(){const f=state.filters;const dates=[...new Set(filtered().map(r=>r.date).filter(Boolean))].sort();return `${f.group||'全部业务'} · ${f.room||'全部直播间'} · ${f.anchor||'全部主播'} · ${f.from||f.to?`${f.from||'最早'} 至 ${f.to||'最新'}`:dates.length?`${dates[0]} 至 ${dates.at(-1)}`:'全部历史'}`;}
function updateRange(){if(!$('range-label'))return;$('range-label').textContent=state.data?rangeDescription():'正在读取数据';const f=state.filters,latest=state.data?.dateRange.to;document.querySelectorAll('[data-range]').forEach(b=>{let active=!f.from&&!f.to&&b.dataset.range==='all';if(latest&&f.to===latest){if(b.dataset.range==='latest')active=f.from===latest;if(['7','30'].includes(b.dataset.range)){const date=new Date(latest+'T00:00:00Z');date.setUTCDate(date.getUTCDate()-Number(b.dataset.range)+1);active=f.from===date.toISOString().slice(0,10);}}b.classList.toggle('active',active);});}
function setDateRange(from,to){state.filters.from=from;state.filters.to=to;$('filter-from').value=from;$('filter-to').value=to;state.tablePage=1;render();}
function applyDateRange(value){if(value==='all'){setDateRange('','');return;}const latest=state.data?.dateRange.to;if(!latest){toast('当前没有有效售卖日期');return;}const date=new Date(latest+'T00:00:00Z');if(value!=='latest')date.setUTCDate(date.getUTCDate()-Number(value)+1);setDateRange(date.toISOString().slice(0,10),latest);}
function insightStrip(records){const products=productGroups(records),leader=products.filter(p=>p.offers>p.pending).sort((a,b)=>b.orders-a.orders)[0],conversion=products.filter(p=>p.rate!==null).sort((a,b)=>b.rate-a.rate)[0],s=summarize(records);return `<div class="insights-strip"><button class="insight" ${leader?`data-product="${esc(leader.key)}"`:'disabled'}><span class="insight-label">${icon('orders')} 订单领先</span><strong>${esc(leader?.name||'暂无已填订单')}</strong><small>${leader?`${fmt(leader.orders)} 单 · ${leader.offers} 条售卖记录`:'等待补充单量'}</small></button><button class="insight" ${conversion?`data-product="${esc(conversion.key)}"`:'disabled'}><span class="insight-label">${icon('trend')} 订单峰值转化领先</span><strong>${esc(conversion?.name||'暂无有效转化数据')}</strong><small>${conversion?`${pct(conversion.rate)} · ${conversion.rated} 条有效记录`:'等待订单和峰值'}</small></button><button class="insight" data-go="quality"><span class="insight-label">${icon('database')} 转化数据覆盖</span><strong>${s.rated} <em>/ ${records.length} 条售卖记录</em></strong><small>加权计算，不对各条转化率取平均</small></button></div>`;}
function averagePeakText(value){return fmt(value,Number.isInteger(value)?0:1);}
function sessionPeakCard(group){const stats=group.sessionPeaks;
 return `<details class="board-session-peaks"><summary><span class="session-peak-label">场次平均峰值人数<small>${stats.validSessionCount?`按 ${stats.validSessionCount} 场完整峰值平均`:'暂无完整场次峰值'}${stats.incompleteSessionCount?` · ${stats.incompleteSessionCount} 场待补`:''}</small></span><strong class="session-average-value">${averagePeakText(stats.averagePeak)} <small>人</small></strong><span class="session-peak-chevron" aria-hidden="true">⌄</span></summary><div class="session-peak-body"><p>每场先合计该组各系统峰值，再按场次取算术平均。同日期、时间、主播记为一场；同场同系统多款产品只计一次，数值不同取最高值。</p><div class="session-peak-list">${stats.sessions.map(session=>`<div class="session-peak-row"><div><strong>${esc(session.date)} · ${esc(session.time)}</strong><span>${esc(session.anchor||'主播未填')}</span><small>${session.rooms.map(r=>`${esc(r.room)} ${r.peak===null?'待补':fmt(r.peak)}`).join(' + ')}${session.conflictingRooms.length?` · ${esc(session.conflictingRooms.join('、'))} 有多个值，已取最高`:''}</small></div><div class="session-peak-total">${session.peak===null?'峰值待补':fmt(session.peak)+' 人'}<small>${session.peak===null?'未计入平均':'计入平均'}</small></div></div>`).join('')||'<p>等待可识别日期与时间的直播记录。</p>'}</div>${stats.incompleteSessionCount?`<p>${stats.incompleteSessionCount} 场有系统峰值缺失，未计入平均；缺失值不按 0 处理。</p>`:''}${stats.unidentifiedRecordCount?`<p>${stats.unidentifiedRecordCount} 条售卖记录缺少日期或时间，未推测所属场次。</p>`:''}<p>各系统峰值可能发生在不同时间，这里显示系统峰值之和，供场次间比较。</p></div></details>`;
}
function roomTable(group,tab){
 if(tab==='products'){
  const products=productGroups(group.records).sort((a,b)=>state.boardSort==='rate'?(b.rate??-1)-(a.rate??-1):state.boardSort==='revenue'?b.revenue-a.revenue:b.orders-a.orders);
  return `<div class="board-table-scroll"><table><thead><tr><th>产品</th><th class="num">订单</th><th class="num">销售额估算</th><th class="num">订单峰值转化</th><th></th></tr></thead><tbody>${products.map((p,i)=>`<tr class="click-row" data-product="${esc(p.key)}" data-room-group="${esc(group.key)}"><td><span class="board-rank">${i+1}</span><span class="board-product-name">${esc(p.name)}${p.bundle?' <span class="chip bundle">组合</span>':''}</span></td><td class="num">${p.offers===p.pending?'—':fmt(p.orders)}</td><td class="num">${p.priced?money(p.revenue):'—'}</td><td class="num cyan">${pct(p.rate)}</td><td><button class="detail-link" data-plan="${esc(p.key)}">备货 ↗</button></td></tr>`).join('')}</tbody></table></div>`;
 }
 return `<div class="board-table-scroll"><table><thead><tr><th>系统</th><th class="num">订单</th><th class="num">销售额估算</th><th class="num">产品数</th><th class="num">订单峰值转化</th><th class="num">场次平均峰值</th><th>数据覆盖</th></tr></thead><tbody>${group.rooms.map(r=>`<tr><td><span class="system-name">${esc(r.room)}</span></td><td class="num">${r.offers===r.pending?'—':fmt(r.orders)}</td><td class="num">${r.priced?money(r.revenue):'—'}</td><td class="num">${r.products}</td><td class="num cyan">${pct(r.rate)}</td><td class="num system-average-peak">${averagePeakText(r.sessionPeaks.averagePeak)}<small class="text-muted"> / ${r.sessionPeaks.validSessionCount} 场</small></td><td><span class="coverage-badge ${r.pending?'warning':''}">${r.rated}/${r.offers} 可计算</span></td></tr>`).join('')}</tbody></table></div>`;
}
function renderRooms(){const records=baseRecords(),groups=roomGroups(records,state.filters.room),s=summarize(filtered());
 $('rooms-view').innerHTML=`<div class="board-summary"><div><span class="live-dot"></span><strong>${groups.length} 组直播间</strong><span>${groups.reduce((n,g)=>n+g.rooms.length,0)} 个系统 · 按当前筛选汇总历史售卖</span></div><label>商品榜排序 <select id="board-sort" aria-label="看板商品排序"><option value="orders" ${state.boardSort==='orders'?'selected':''}>订单数</option><option value="rate" ${state.boardSort==='rate'?'selected':''}>转化率</option><option value="revenue" ${state.boardSort==='revenue'?'selected':''}>销售额估算</option></select></label></div>
 <div class="room-board-grid">${groups.map((g,i)=>{const tab=state.boardTabs[g.key]||'systems';return `<article class="room-board" data-room-group="${esc(g.key)}" style="--group-accent:${['var(--blue)','var(--purple)','var(--orange)','var(--green)'][i%4]}"><div class="board-head"><span class="group-avatar">${esc(g.key)}</span><div><h2>${esc(g.key)} 组直播间</h2><p>${g.rooms.map(r=>esc(r.room)).join(' / ')} · ${g.sourceRecords} 条原表售卖记录</p></div><span class="coverage-badge ${g.pending?'warning':''}">${g.pending?g.pending+' 条系统单量待补':'单量已填'}</span></div><div class="board-hero"><div><small>已记录订单</small><strong>${g.offers===g.pending?'—':fmt(g.orders)}</strong></div><div class="conversion-hero"><small>订单峰值转化率 <span class="recalc">加权</span></small><strong>${pct(g.rate)}</strong></div></div>${sessionPeakCard(g)}<div class="board-metric-grid"><div><small>销售额估算</small><strong>${g.priced?money(g.revenue):'—'}</strong></div><div><small>售卖产品</small><strong>${fmt(g.products)} <em>款</em></strong></div><div><small>有效转化样本</small><strong>${g.rated}<em> / ${g.offers} 条系统记录</em></strong></div><div><small>对应样本峰值合计</small><strong>${g.rated?fmt(g.peak):'—'} <em>人次</em></strong></div></div><div class="board-rate-caption"><span>转化率 = 有效订单合计 ÷ 对应样本峰值合计</span><span>${g.rated?'已按合并口径重算':'等待有效样本'}</span></div><div class="board-tabs" role="group" aria-label="${esc(g.key)}组明细视图"><button data-board-group="${esc(g.key)}" data-board-tab="systems" class="${tab==='systems'?'active':''}">分系统明细</button><button data-board-group="${esc(g.key)}" data-board-tab="products" class="${tab==='products'?'active':''}">产品成交榜</button></div>${roomTable(g,tab)}<div class="board-note">组合品订单计一次；缺失的系统单量留空。${g.pending?' 当前统计包含待补记录，订单和估算金额尚不完整。':''}</div></article>`;}).join('')||'<div class="empty-state"><h2>当前范围暂无直播间明细</h2><p>调整日期、业务或主播筛选后重试。</p></div>'}</div><p class="section-note">看板仅汇总原表已分配到各系统的单量、峰值和组件件数。${!state.filters.room?`总表有 ${s.offers} 条售卖记录；系统明细缺失时，分组之和可能与总表不同。`:''} 场次平均峰值人数按同场系统峰值去重相加，再跨场次平均；可展开查看明细。同一系统在不同产品的峰值会重复出现，因此用于转化率的“样本峰值合计”不是直播间去重人数或同时在线峰值。</p>`;
}
function showHistory(){if(!state.data){toast('数据尚未就绪');return;}const rows=dailySummaries(filtered(true));$('tool-content').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">HISTORY</span><h2>历史售卖回看</h2><p>按原表直播日期归档 · 保留当前业务、主播和直播间筛选</p></div><button class="dialog-close" id="close-tool" aria-label="关闭">×</button></div><div class="dialog-body"><div class="history-list">${rows.map(d=>`<button class="history-day" data-history-date="${esc(d.date)}"><span class="history-date"><strong>${esc(d.date.slice(5).replace('-',' / '))}</strong><small>${d.date.slice(0,4)} · ${d.products} 款产品</small></span><span><small>已记录订单</small><strong>${d.offers===d.pending?'—':fmt(d.orders)}</strong></span><span><small>订单峰值转化率</small><strong class="cyan">${pct(d.rate)}</strong></span><span class="history-day-action">${d.pending?`<em>${d.pending} 条待补</em>`:''}查看当天 ↗</span></button>`).join('')||'<div class="empty-state"><p>当前范围没有带有效日期的售卖记录。</p></div>'}</div><p class="section-note">历史数据来自当前原表，原表补填后刷新即可更新。每个日期可包含多次售卖。</p></div>`;$('tool-dialog').showModal();}
function showReport(){if(!state.data){toast('数据尚未就绪');return;}const records=filtered(),s=summarize(records),products=productGroups(records),leaders=products.filter(p=>p.offers>p.pending).sort((a,b)=>b.orders-a.orders).slice(0,5),rates=products.filter(p=>p.rate!==null).sort((a,b)=>b.rate-a.rate).slice(0,5),groups=roomGroups(baseRecords(),state.filters.room);
 const lines=['产品数据工作台 · 销售分析报告',rangeDescription(),`源数据成功同步：${time(state.data.fetchedAt)}`,state.status?.error?'刷新状态：最新读取失败，以下为上次成功数据。':'', '',`售卖产品：${s.products} 款；售卖记录：${s.offers} 条`, `已记录订单：${s.offers===s.pending?'—':fmt(s.orders)} 单`, `销售额估算：${s.priced?money(s.revenue):'—'}（直播价 × 订单，未扣退款）`, `加权订单峰值转化率：${pct(s.rate)}（${s.rated} 条有效记录）`, `待补单量：${s.pending} 条`, '', '产品订单排行',...leaders.map((p,i)=>`${i+1}. ${p.name}${p.bundle?' [组合品]':''}：${fmt(p.orders)} 单，转化率 ${pct(p.rate)}${p.pending?'；另有 '+p.pending+' 条待补':''}`),leaders.length?'':'暂无完整订单', '', '产品订单峰值转化排行',...rates.map((p,i)=>`${i+1}. ${p.name}：${pct(p.rate)}，${p.rated} 条有效记录`),rates.length?'':'暂无有效转化数据', '', '直播间分组汇总（按已填系统明细）',...groups.map(g=>`${g.key} 组 [${g.rooms.map(r=>r.room).join('/')}]：${g.offers===g.pending?'—':fmt(g.orders)} 单，转化率 ${pct(g.rate)}，场次平均峰值 ${averagePeakText(g.sessionPeaks.averagePeak)} 人（${g.sessionPeaks.validSessionCount} 场完整峰值${g.sessionPeaks.incompleteSessionCount?`，另 ${g.sessionPeaks.incompleteSessionCount} 场待补`: ""}）${g.pending?'；'+g.pending+' 条系统单量待补':''}`),'', '计算说明：组合品订单和销售额只计一次，备货按组件拆分。转化率按有效订单合计 ÷ 对应峰值合计重算，不是去重用户购买率；跨产品峰值可能重复计入。系统明细不全时，分组之和可能与总表不同。备货独立评估该产品全部有效历史，采用去掉两端极值后的各场等权平均；不足 3 场需手动确认转化率。',...(state.data.sourceUrl?[`原始文档：${state.data.sourceUrl}`]:[])];
 state.reportText=lines.join('\n');$('tool-content').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">SALES REPORT</span><h2>产品销售分析报告</h2><p>基于当前筛选范围 · ${s.offers} 条售卖记录</p></div><button class="dialog-close" id="close-tool" aria-label="关闭">×</button></div><div class="dialog-body"><textarea id="report-text" class="report-text" readonly aria-label="销售分析报告">${esc(state.reportText)}</textarea><div class="dialog-actions"><span class="text-muted">包含订单、转化排行、直播间分组和数据口径</span><button class="button outline" id="download-report">${icon('download')} 下载报告</button><button class="button primary" id="copy-report">复制文本</button></div></div>`;$('tool-dialog').showModal();}
async function copyReport(){try{await navigator.clipboard.writeText(state.reportText);toast('报告已复制');}catch{$('report-text').focus();$('report-text').select();toast('请按 ⌘C 或 Ctrl+C 复制已选中的报告');}}
function downloadReport(){const url=URL.createObjectURL(new Blob([state.reportText],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='产品销售分析报告.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('报告已下载');}

function setSourceRefresh(enabled){
 sourceRefreshEnabled=cloud&&enabled;
 $('source-update-help').hidden=!cloud;
 $('source-update').hidden=!cloud;
 $('source-refresh-toggle').setAttribute('aria-checked',String(sourceRefreshEnabled));
 $('source-refresh-toggle').lastElementChild.textContent=remoteSource?'自动同步':'读取原表';
 $('source-refresh-toggle').setAttribute('aria-label',remoteSource?'打开或刷新网页时自动读取企业微信原表':'重新读取企业微信原表');
 $('source-refresh-hint').textContent=remoteSource?(sourceRefreshEnabled?'手机、电脑打开或刷新页面时自动同步，读取期间可继续查看已保存数据。':'自动读取已关闭；可点击「重新读取原表」手动同步。'):(sourceRefreshEnabled?'开启后，点击「读取原表并发布」，在更新电脑上完成更新。':'关闭时，只获取上次成功发布的数据。');
 $('source-refresh-toggle').title=$('source-refresh-hint').textContent;
 $('refresh').hidden=!remoteSource&&sourceRefreshEnabled;
 $('source-refresh-link').hidden=remoteSource||!sourceRefreshEnabled;
 $('snapshot-refresh').hidden=remoteSource||!sourceRefreshEnabled;
 try{localStorage.setItem(remoteSource?'workbench-auto-source':'workbench-read-source',String(sourceRefreshEnabled));}catch{}
}
function showSourceUpdate(){
 if(remoteSource){
  $('tool-content').innerHTML='<div class="dialog-head"><div><h2>云端自动同步</h2><p>手机和电脑共享同一份原表数据。</p></div><button class="dialog-close" id="close-tool" aria-label="关闭">×</button></div><div class="dialog-body source-update-guide"><p>开启顶部「自动同步」后，每次打开或刷新网页都会发起云端读取，无需启动本机服务。也可随时点击「重新读取原表」手动更新。</p><p>同步时先显示上次成功保存的数据，销售表和价格表全部读取、校验成功后再更新。数据更新时间是实际读取原表成功的时间。</p><p>多人同时刷新会合并为同一轮读取；10 秒内连续完成的刷新复用刚获取的数据，避免重复请求。授权失效或同步失败时会保留上次成功数据并明确提示。</p></div>';
  $('tool-dialog').showModal();return;
 }
 $('tool-content').innerHTML='<div class="dialog-head"><div><h2>更新原表并发布</h2><p>更新后，其他人仍使用原来的分享网址。</p></div><button class="dialog-close" id="close-tool" aria-label="关闭">×</button></div><div class="dialog-body source-update-guide"><p>请在保存了企业微信授权的更新电脑上操作：</p><ol><li>先双击「启动产品分析」，启动本机服务。</li><li>开启顶部「读取原表」，点击「读取原表并发布」。</li><li>在打开的本机页面等待「云端已更新」，再回到分享页，点击「获取已发布数据」。</li></ol><p>也可以直接双击「更新分享网站」，自动读取并发布。</p><small>只需更新时让这台电脑开机联网。发布完成后即可关机，其他人仍可查看已发布的数据。手机和其他电脑可获取已发布数据。</small></div>';
 $('tool-dialog').showModal();
}
setSourceRefresh(sourceRefreshEnabled);
$('source-refresh-link').addEventListener('click',()=>toast('请在本机更新页等待发布完成'));

let pollTimer=null;
function syncStatus(status){state.status=status;$('refresh').disabled=status.running;$('refresh').classList.toggle('spin',status.running);$('refresh').innerHTML=`${icon('refresh')}<span>${status.running?'正在刷新…':remoteSource?'重新读取原表':cloud?'获取已发布数据':'读取原表并发布'}</span>`;$('sync-bar').className=`sync-bar ${status.running?'running':status.error?'error':''}`;$('sync-message').textContent=status.running?`${status.message}${status.step!=null?`（${status.step}/${status.total}）`:''}`:status.error?`${status.error} ${state.data?'当前显示上次成功的数据。':''}`:state.data?(remoteSource?(status.fetchedAt?'已同步企业微信 · 所有设备共享数据已更新':'已载入云端保存数据'):cloud?'已载入云端最新发布数据 · 修改原表后请开启顶部开关读取并发布':status.publicationEnabled?status.message==='已获取最新数据'?'已同步企业微信 · 云端已更新':status.message:'已同步企业微信 · 打开页面自动刷新'):status.message;$('sync-time').textContent=state.data?`数据更新时间 ${time(state.data.fetchedAt)}`:'';}
async function poll(){try{const status=await requestStatus();syncStatus(status);if(status.running){pollTimer=setTimeout(poll,1400);}else{const payload=await requestData();setData(payload.data);syncStatus(payload.status);if(!status.error)toast(status.publicationEnabled?'原表已刷新，云端分享已更新':'已获取最新的产品数据');else if(!state.data)render();}}catch(error){syncStatus({...state.status,running:false,error:error.message});}}
async function startRefresh(){clearTimeout(pollTimer);syncStatus({running:true,step:0,total:1,message:remoteSource?'正在从云端连接企业微信…':cloud?'正在获取已发布数据…':'正在连接企业微信…',error:null});try{const payload=await requestRefresh();if(cloud&&!remoteSource){const unchanged=state.data?.fetchedAt===payload.data.fetchedAt;setData(payload.data);syncStatus(payload.status);toast(unchanged?'已是最新发布版本':'已载入云端最新发布数据');}else{syncStatus(payload);pollTimer=setTimeout(poll,1000);}}catch(error){syncStatus({running:false,error:error.message});render();}}
document.addEventListener('click',event=>{const t=event.target.closest('button,[data-product]');if(!t)return;if(t.id==='theme-toggle'){applyTheme(document.documentElement.dataset.theme==='light'?'dark':'light');return;}if(t.dataset.business!==undefined){state.filters.group=t.dataset.business;state.tablePage=1;populateFilters();render();return;}if(t.dataset.page){navigate(t.dataset.page);return;}if(t.dataset.go){navigate(t.dataset.go);return;}if(t.dataset.plan){planFor(t.dataset.plan);return;}if(t.dataset.product){showProduct.roomGroup=t.dataset.roomGroup||null;showProduct(t.dataset.product);return;}if(t.dataset.boardTab){state.boardTabs[t.dataset.boardGroup]=t.dataset.boardTab;renderRooms();return;}if(t.dataset.historyDate){setDateRange(t.dataset.historyDate,t.dataset.historyDate);$('tool-dialog').close();navigate('rooms');return;}if(t.dataset.range){applyDateRange(t.dataset.range);return;}if(t.id==='show-history'){showHistory();return;}if(t.id==='show-report'){showReport();return;}if(t.id==='close-tool')$('tool-dialog').close();if(t.id==='copy-report')copyReport();if(t.id==='download-report')downloadReport();if(t.dataset.rate){state.rateMode=t.dataset.rate;render();return;}if(t.id==='source-refresh-toggle'){setSourceRefresh(!sourceRefreshEnabled);if(remoteSource&&sourceRefreshEnabled&&!state.status?.running)startRefresh();return;}if(t.id==='source-update'){showSourceUpdate();return;}if(t.id==='refresh'||t.id==='snapshot-refresh')startRefresh();if(t.id==='reset-filters'){state.filters={group:'',room:'',anchor:'',from:'',to:''};['group','room','anchor','from','to'].forEach(k=>$(`filter-${k}`).value='');populateFilters();state.tablePage=1;render();}if(t.id==='prev-page'){state.tablePage--;render();}if(t.id==='next-page'){state.tablePage++;render();}if(t.id==='export-products')exportProducts();if(t.id==='export-stock')exportStock();if(t.id==='close-dialog'||t.id==='close-dialog-bottom')$('product-dialog').close();if(t.id==='stock-reset'){Object.assign(state.stock,{audience:'',buffer:10,customRate:'',stock:{},quantities:{}});renderStock();}});
document.addEventListener('change',event=>{const t=event.target;if(t.id?.startsWith('filter-')){state.filters[t.id.slice(7)]=t.value;if(t.id==='filter-group')populateFilters();state.tablePage=1;render();}if(t.id==='board-sort'){state.boardSort=t.value;renderRooms();}if(t.id==='product-sort'){state.sort=t.value;render();}if(t.id==='stock-business'){state.stock.business=t.value;const product=productGroups(state.data.records.filter(r=>r.group===t.value)).sort((a,b)=>b.orders-a.orders)[0];planFor(product?.key||'');}const fields={'stock-mechanism':'mechanismKey'};if(fields[t.id]){state.stock[fields[t.id]]=t.value;state.stock.audience='';state.stock.customRate='';if(t.id==='stock-mechanism'){state.stock.quantities={};state.stock.stock={};}renderStock();}if(t.dataset.quantity!==undefined||t.dataset.stock!==undefined){const components=state.data.records.find(r=>r.productKey===state.stock.productKey&&r.mechanismKey===state.stock.mechanismKey)?.components||[];const index=Number(t.dataset.quantity??t.dataset.stock),name=components[index]?.name;if(name){state.stock[t.dataset.quantity!==undefined?'quantities':'stock'][name]=t.value;renderStockResult();}}});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='product-search'){const pos=t.selectionStart;state.search=t.value;state.tablePage=1;renderProducts();$('product-search').focus();$('product-search').setSelectionRange(pos,pos);}const fields={'stock-audience':'audience','stock-buffer':'buffer','stock-custom-rate':'customRate'};if(fields[t.id]){state.stock[fields[t.id]]=t.value;renderStockResult();}});
$('product-dialog').addEventListener('click',e=>{if(e.target===$('product-dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close();}});
$('tool-dialog').addEventListener('click',e=>{if(e.target===$('tool-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
navigate(location.hash.slice(1)||'overview');
if(!cloud||remoteSource){try{const payload=await requestData();setData(payload.data);syncStatus(payload.status);}catch(error){syncStatus({running:false,error:error.message});}}
// One fresh read per page opening, shared on the server if another tab is already refreshing.
if(!remoteSource||sourceRefreshEnabled)startRefresh();
window.addEventListener('pageshow',event=>{if(event.persisted&&(!remoteSource||sourceRefreshEnabled))startRefresh();});
